"use client";

import React, { useState } from "react";
import { useRouter, useSearchParams } from "next/navigation";
import Link from "next/link";
import { Mail, Lock, ArrowRight, Loader2, AlertCircle, CheckCircle2 } from "lucide-react";
import { AuthInputField } from "../common/AuthInputField";
import { authApi } from "@/lib/authApi";
import { useAuth } from "@/context/AuthContext";

export const LoginForm: React.FC = () => {
  const router = useRouter();
  const searchParams = useSearchParams();
  const { saveAuthSession } = useAuth();

  const initialEmail = searchParams.get("email") || "";
  const registeredSuccess = searchParams.get("registered") === "true";
  const resetSuccess = searchParams.get("reset") === "true";

  const [email, setEmail] = useState(initialEmail);
  const [password, setPassword] = useState("");
  const [rememberMe, setRememberMe] = useState(true);
  const [loading, setLoading] = useState(false);
  const [errorMessage, setErrorMessage] = useState<string | null>(null);
  const [successMessage, setSuccessMessage] = useState<string | null>(
    registeredSuccess
      ? "Account registered and verified successfully! Please log in."
      : resetSuccess
      ? "Password reset successfully! Please log in with your new password."
      : null
  );

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setErrorMessage(null);

    if (!email.trim()) {
      setErrorMessage("Please enter your email address.");
      return;
    }
    if (!password) {
      setErrorMessage("Please enter your password.");
      return;
    }

    try {
      setLoading(true);
      const res = await authApi.login(email, password, rememberMe);

      if (res.status && res.token && res.data) {
        setSuccessMessage("Login Successful! Navigating to Landing page...");
        saveAuthSession(res.token, res.data);
        setTimeout(() => {
          router.push("/");
        }, 800);
      } else {
        const errorText =
          res.message ||
          (res.errors
            ? Object.values(res.errors).flat().join(". ")
            : "Invalid email or password. Please try again.");
        setErrorMessage(errorText);
      }
    } catch (err: any) {
      setErrorMessage(
        err?.message || "Connection failed. Please check your network and try again."
      );
    } finally {
      setLoading(false);
    }
  };

  return (
    <form onSubmit={handleSubmit} className="space-y-4">
      {/* Success Notification Banner */}
      {successMessage && (
        <div className="p-3.5 rounded-xl bg-green-50 border border-green-200 text-green-800 text-xs font-semibold flex items-center gap-3">
          <CheckCircle2 className="w-5 h-5 flex-shrink-0 text-[#71AC16]" />
          <span>{successMessage}</span>
        </div>
      )}

      {/* Error Notification Banner */}
      {errorMessage && (
        <div className="p-3.5 rounded-xl bg-red-50 border border-red-200 text-red-700 text-xs font-semibold flex items-start gap-3">
          <AlertCircle className="w-5 h-5 flex-shrink-0 text-red-500 mt-0.5" />
          <div className="flex-1 leading-relaxed">{errorMessage}</div>
        </div>
      )}

      {/* Email Input */}
      <AuthInputField
        label="Email Address"
        type="email"
        name="email"
        value={email}
        onChange={(e) => setEmail(e.target.value)}
        placeholder="warrior@example.com"
        icon={<Mail className="w-4 h-4" />}
        required
        autoComplete="email"
      />

      {/* Password Input */}
      <AuthInputField
        label="Password"
        type="password"
        name="password"
        value={password}
        onChange={(e) => setPassword(e.target.value)}
        placeholder="••••••••••••"
        icon={<Lock className="w-4 h-4" />}
        required
        autoComplete="current-password"
      />

      {/* Remember Me and Forgot Password */}
      <div className="flex items-center justify-between text-xs pt-1 select-none">
        <label className="flex items-center gap-2 cursor-pointer text-neutral-600 hover:text-neutral-900">
          <input
            type="checkbox"
            checked={rememberMe}
            onChange={(e) => setRememberMe(e.target.checked)}
            className="w-4 h-4 rounded border-neutral-300 text-[#71AC16] focus:ring-[#71AC16] accent-[#71AC16]"
          />
          <span className="font-medium">Remember me</span>
        </label>

        <Link
          href="/forgot-password"
          className="font-semibold text-neutral-600 hover:text-[#71AC16] transition-colors"
        >
          Forgot password?
        </Link>
      </div>

      {/* Submit Button */}
      <button
        type="submit"
        disabled={loading}
        className="w-full mt-2 py-3 px-6 rounded-full bg-[#71AC16] hover:bg-[#639912] active:scale-[0.98] text-white font-black uppercase tracking-wider text-sm transition-all shadow-md shadow-[#71AC16]/20 flex items-center justify-center gap-2 cursor-pointer disabled:opacity-60 disabled:cursor-not-allowed select-none"
      >
        {loading ? (
          <>
            <Loader2 className="w-5 h-5 animate-spin" />
            <span>Signing in...</span>
          </>
        ) : (
          <>
            <span>Log In</span>
            <ArrowRight className="w-4 h-4 stroke-[3]" />
          </>
        )}
      </button>

      {/* Quick Demo Pre-fill */}
      <div className="pt-2">
        <div className="flex items-center justify-between p-2.5 rounded-xl bg-neutral-50 border border-neutral-200 text-xs">
          <span className="text-neutral-500">Quick sample account?</span>
          <button
            type="button"
            onClick={() => {
              setEmail("user@gmail.com");
              setPassword("password");
            }}
            className="text-[#71AC16] hover:underline font-bold cursor-pointer"
          >
            Pre-fill credentials
          </button>
        </div>
      </div>
    </form>
  );
};
